        /// <summary>
        /// ekzekuton prc_T_NIVELREGJISTRIMI_ins ne DB dhe kthen statusin e perfundimit te ekzekutimit te SP-se perkatese
        /// Shiko clsMesazh brenda ketij moduli per informacion te metejshem mbi vleren e kthimit te kesaj metode
        /// <param name="akt"> gjendjen aktive ose jo te nivelit</param>
        /// <param name="idKat"> id e kategorise ne te cilen ben pjese niveli</param>
        /// <param name="idNiv"> id ritese e nivelit</param>
        /// <param name="kod"> kodi i nivelit</param>
        /// <param name="nderm"> id e ndermarjes qe i perket ky nivel</param>
        /// <param name="pershk"> pershkrimi</param>
        /// <param name="radh"> radha </param>
        /// <returns> nje objekt clsMesazh qe tregon nese ruajtja eshte kryer ne rregull apo jo.</returns>
        /// </summary>
        internal clsMesazh ruajNivelRegjistrimi(out int idNiv, int idKat, string kod, string pershk, int radh, bool akt, int nderm, int idperdoruesi, int idstatusdok, bool nrSerialUnik)
        {
            idNiv = -1;
            dbManager.Open();
            dbManager.CreateParameters(10);
            dbManager.AddParameters(0, "@IDNIVEL", idNiv, ParameterDirection.Output);
            dbManager.AddParameters(1, "@IDKATDOK", idKat, ParameterDirection.Input);
            dbManager.AddParameters(2, "@KODI", kod, ParameterDirection.Input);
            dbManager.AddParameters(3, "@PERSHK", pershk, ParameterDirection.Input);
            dbManager.AddParameters(4, "@RADHA", radh, ParameterDirection.Input);
            dbManager.AddParameters(5, "@AKTIV", akt, ParameterDirection.Input);
            dbManager.AddParameters(6, "@IDNDERMARRJE", nderm, ParameterDirection.Input);
            dbManager.AddParameters(7, "@IDPERDORUESI", idperdoruesi, ParameterDirection.Input);
            dbManager.AddParameters(8, "@IDSTATUSDOK", idstatusdok, ParameterDirection.Input);
            dbManager.AddParameters(9, "@NRSERIALUNIK", nrSerialUnik, ParameterDirection.Input);
            dbManager.ExecuteNonQuery(CommandType.StoredProcedure, "prc_T_NIVELREGJISTRIMI_ins");
            idNiv = int.Parse(dbManager.Parameters[0].Value.ToString());
            return new clsMesazh(true, "Ruajtja perfundoi me sukses");
        }

        /// <summary>
        /// Shton te drejtat per nivelin e ri te rregjistrimit qe po shtohet
        /// </summary>
        /// <returns>Nese shtimi u krye me sukses ose jo</returns>
        public clsMesazh shtoTeDrejtaPerNivelRegjistrimi(int idNiveli, int idNdermarrje, int idKatDok)
        {
            this.dbManager.Open();
            dbManager.CreateParameters(3);
            dbManager.AddParameters(0, "@IDNIVELREGJISTRIMI", idNiveli, ParameterDirection.Input);
            dbManager.AddParameters(1, "@IDNDERMARRJE", idNdermarrje, ParameterDirection.Input);
            dbManager.AddParameters(2, "@IDKATDOK", idKatDok, ParameterDirection.Input);
            int sukses = dbManager.ExecuteNonQuery(CommandType.StoredProcedure, "prc_T_ROLDREJTATRUPI_ins_nivelRegjistrimi");

            if (sukses > 0)
                return new clsMesazh(true, "Ruajtja e te drejtave per nivelin përfundoi me sukses!");
            else
                return new clsMesazh(false, "Ndodhi një gabim gjatë ruajtjes se drejtave per nivelin!");
        }
        /// <summary>
        /// Heq rreshtat e te drejtat per nivelin e rregjistrimit qe po fshihet
        /// </summary>
