        internal DataRow ktheKokaShitjeSipasID(int idShitjeKoka)
        {
            ImbLogger.LogTraceShitje($"Filloi metoda ktheKokaShitjeSipasID nga DB sipas idShitjeKoka:{idShitjeKoka}");
            dbManager.Open();
            dbManager.CreateParameters(1);
            dbManager.AddParameters(0, "@IDSHITJEKOKA", idShitjeKoka, ParameterDirection.Input);
            DataSet ds = dbManager.ExecuteDataSet(CommandType.StoredProcedure, "prc_T_KOKASHITJE_sel");
            if (ds == null)
            {
                ImbLogger.LogWarningShitje($"Metoda ktheKokaShitjeSipasID sipas idShitjeKoka:{idShitjeKoka} ktheu null !");
                return null;
            }
            if (ds.Tables[0].Rows.Count == 0 || ds.Tables[0].Rows.Count > 1)
            {
                ImbLogger.LogWarningShitje($"Metoda ktheKokaShitjeSipasID sipas idShitjeKoka:{idShitjeKoka} ktheu null !");
                return null;
            }

            ImbLogger.LogWarningShitje($"Mbaroi metoda ktheKokaShitjeSipasID sipas idShitjeKoka:{idShitjeKoka}!");
            return ds.Tables[0].Rows[0];
        }


