        internal bool eshteDokKonvertuarNgaNiveli(int idDok, int idNderm, string kodNiveli)
        {
            ImbLogger.LogTraceShitje($"Filloi metoda eshteDokKonvertuarNgaNiveli me parametra idDok:{idDok}, idNderm:{idNderm}, kodNiveli:"+kodNiveli);
            dbManager.Open();
