            dbManager.AddParameters(1, "@IDDOK", idDok, ParameterDirection.Input);
            dbManager.AddParameters(2, "@KODNIVEL", kodNiveli, ParameterDirection.Input);
            int nr = Convert.ToInt32(dbManager.ExecuteScalar(CommandType.StoredProcedure, "prc_T_KOKASHITJE_vjenNgaKonvertimi"));
            if (nr > 0)
            {
                ImbLogger.LogTraceShitje($"Mbaroi metoda eshteDokKonvertuarNgaNiveli me parametra idDok:{idDok}, idNderm:{idNderm}, kodNiveli:" + kodNiveli);
                return true;
            }
            else
            {
                ImbLogger.LogTraceShitje($"Mbaroi metoda eshteDokKonvertuarNgaNiveli me parametra idDok:{idDok}, idNderm:{idNderm}, kodNiveli:" + kodNiveli);
                return false;
            }

        }
