        /// <summary>
        /// ekzekuton prc_T_TRUPISHITJE_ins ne DB dhe kthen statusin e perfundimit te ekzekutimit te SP-se perkatese
        /// Shiko clsMesazh brenda ketij moduli per informacion te metejshem mbi vleren e kthimit te kesaj metode
        /// </summary>
        /// <param name="cm">cmimi </param>
        /// <param name="IdDetaj"> id e detajimit te artikullit</param>
        /// <param name="idLlojVep"> id e llojit te veprimit</param>
        /// <param name="idMagazina"> id e magazines</param>
        /// <param name="idNjes"> id e njesise se artikullit</param>
        /// <param name="idShiKoka"> id e kokes se dokumentit te shitje blerjes</param>
        /// <param name="idShiTrup">id ritese e trupit te dokumentit te shitjes blerjes</param>
        /// <param name="kod"> kodi i artikullit, llogarise etj</param>
        /// <param name="pershkr"> pershkrimi i artikullit, llogarise etj</param>
        /// <param name="sas"> sasia</param>
        /// <param name="tv"> tvsh</param>
        /// <param name="vlMeTv">vlefta me tvsh</param>
        /// <param name="vlPaTv"> vlefta pa tvsh</param>
        /// <param name="zbr">zbritja analitike</param>
        /// <param name="idkodi">id e kodit</param>
        /// <param name="iddet2"> detajimi i dyte i artikullit</param>
        /// <returns> nje objekt clsMesazh qe tregon nese ruajtja eshte kryer ne rregull apo jo.</returns>

        internal clsMesazh ruajTrupiShitje(out int idShiTrup, int idShiKoka, int idLlojVep, string kod, string pershkr, int IdDetaj, int idNjes, double sas, double cm, double zbr,
            double vlMeTv, double tv, double vlPaTv, int idMagazina, int idkodi, int iddet2, double gjeresi, double gjatesi, double sasipermasa, string shenime, DateTime dtFillimi, 
            DateTime dtMbarimi, int idtrupikonvertimi, double sasirez, int idtrupirez, int idtrupitransferim, int idLlogShpenzimi, int idtrupikthim, int idtrupikonvertimblerje, 
            string shenime2, int llojzbritje, double zbritjevlere, int idkategorishpenzimi, int idBarkodi, int idTrupiTransferimNga, double vleraKomisionit, bool meKomision)
        {
            idShiTrup = -1;

            dbManager.Open();
            dbManager.CreateParameters(37);
            dbManager.AddParameters(0, "@IDSHITJETRUPI", idShiTrup, ParameterDirection.Output);
            dbManager.AddParameters(1, "@IDSHITJEKOKA", idShiKoka, ParameterDirection.Input);
            dbManager.AddParameters(2, "@IDLLOJVEPRIMI", idLlojVep, ParameterDirection.Input);
            dbManager.AddParameters(3, "@KODI", kod, ParameterDirection.Input);
            dbManager.AddParameters(4, "@PERSHKRIMI", pershkr, ParameterDirection.Input);
            if (IdDetaj == 0 || IdDetaj == -1) dbManager.AddParameters(5, "@IDDETAJIMART", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(5, "@IDDETAJIMART", IdDetaj, ParameterDirection.Input);
            if (idNjes == 0 || idNjes == -1) dbManager.AddParameters(6, "@IDNJESIA", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(6, "@IDNJESIA", idNjes, ParameterDirection.Input);
            dbManager.AddParameters(7, "@SASIA", sas, ParameterDirection.Input);
            dbManager.AddParameters(8, "@CMIMI", cm, ParameterDirection.Input);
            dbManager.AddParameters(9, "@ZBRITJE", zbr, ParameterDirection.Input);
            dbManager.AddParameters(10, "@VLEFTAPATVSH", vlPaTv, ParameterDirection.Input);

            if (tv == 0) dbManager.AddParameters(11, "@TVSH", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(11, "@TVSH", tv, ParameterDirection.Input);

            dbManager.AddParameters(12, "@VLEFTAMETVSH", vlMeTv, ParameterDirection.Input);
            if (idMagazina == 0 || idMagazina == -1) dbManager.AddParameters(13, "@IDMAGAZINA", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(13, "@IDMAGAZINA", idMagazina, ParameterDirection.Input);
            if (iddet2 == 0 || iddet2 == -1) dbManager.AddParameters(14, "@IDDETAJIMART2", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(14, "@IDDETAJIMART2", iddet2, ParameterDirection.Input);
            if (idkodi == 0 || idkodi == -1) dbManager.AddParameters(15, "@IDKODI", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(15, "@IDKODI", idkodi, ParameterDirection.Input);
            dbManager.AddParameters(16, "@GJERESI", gjeresi, ParameterDirection.Input);
            dbManager.AddParameters(17, "@GJATESI", gjatesi, ParameterDirection.Input);
            dbManager.AddParameters(18, "@SASIPERMASE", sasipermasa, ParameterDirection.Input);
            dbManager.AddParameters(19, "@SHENIME", shenime, ParameterDirection.Input);
            dbManager.AddParameters(20, "@DTFILLIMI", dtFillimi, ParameterDirection.Input);
            dbManager.AddParameters(21, "@DTMBARIMI", dtMbarimi, ParameterDirection.Input);
            if (idtrupikonvertimi == 0 || idtrupikonvertimi == -1) dbManager.AddParameters(22, "@IDTRUPIKONVERTIMI", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(22, "@IDTRUPIKONVERTIMI", idtrupikonvertimi, ParameterDirection.Input);

            dbManager.AddParameters(23, "@SASIREZ", sasirez, ParameterDirection.Input);
            if (idtrupirez == 0 || idtrupirez == -1)
                dbManager.AddParameters(24, "@IDTRUPIREZERVIMI", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(24, "@IDTRUPIREZERVIMI", idtrupirez, ParameterDirection.Input);
            if (idtrupitransferim == 0 || idtrupitransferim == -1)
                dbManager.AddParameters(25, "@IDTRUPITRANSFERIMI", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(25, "@IDTRUPITRANSFERIMI", idtrupitransferim, ParameterDirection.Input);
            if (idLlogShpenzimi == 0 || idLlogShpenzimi == -1)
                dbManager.AddParameters(26, "@IDLLOGSHPENZIMI", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(26, "@IDLLOGSHPENZIMI", idLlogShpenzimi, ParameterDirection.Input);
            if (idtrupikthim == 0 || idtrupikthim == -1)
                dbManager.AddParameters(27, "@IDTRUPIKTHIMI", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(27, "@IDTRUPIKTHIMI", idtrupikthim, ParameterDirection.Input);
