            dbManager.AddParameters(6, "@IDSTATUSDOK", idSt, ParameterDirection.Input);

            dbManager.AddParameters(7, "@IDPERDORUESI", idPer, ParameterDirection.Input);
            dbManager.AddParameters(8, "@DTREGJ", dtRegj, ParameterDirection.Input);

            if (pershkrimi == "")
