        /// <summary>
        /// ekzekuton prc_T_KOKAMAGAZINA_ins ne DB dhe kthen statusin e perfundimit te ekzekutimit te SP-se perkatese
        /// Shiko clsMesazh brenda ketij moduli per informacion te metejshem mbi vleren e kthimit te kesaj metode
        /// <param name="dtDk"> data e dokumentit te magazines</param>
        /// <param name="dtRegj"> data e regjistrimit te dokumentit te magazines</param>
        /// <param name="idKonf"> id e konfigurimit te dokumentit</param>
        /// <param name="idLidhes">id e dokumentit nga e cila gjenerohet ne rastet e modifikimit </param>
        /// <param name="idMag">id e magazines</param>
        /// <param name="idKoka">id ritese e kokes se magazines</param>
        /// <param name="idNder"> id e ndermarjes</param>
        /// <param name="idNdVt"> id e ndermarje vitit</param>
        /// <param name="idNiv"> id e nivelit te regjistrimit</param>
        /// <param name="idPer"> id e perdoruesit se e ben regjistrimin</param>
        /// <param name="idSt"> id e statusit te dokumentit</param>
        /// <param name="nrDk">nr i dokumentit</param>
        /// <param name="vl"> vlera totale e dokumentit</param>
        /// <param name="idGjenerues">id e dokumentit nga gjenerohet magazina nga nje ambjent tjeter</param>
        /// <param name="idKonfigGjenerues">id e konfigurimit nga gjenerohet dokumenti</param>
        /// <param name="idNivelGjenerues">id e nivelit nga gjenerohet dokumenti</param>
        /// <returns> nje objekt clsMesazh qe tregon nese ruajtja eshte kryer ne rregull apo jo.</returns>
        /// </summary>
        internal int ruajKokaNdryshimCmimSasi(int idKoka, int idNiv, int idKonf, int idMag, DateTime dtDk, string nrDk, int idLidhes, double vl, int idSt, int idNder, int idNdVt, int idPer, DateTime dtRegj, int idNivelGjenerues, int idKonfigGjenerues, int idGjenerues, int iddegeadministrative, int idllog, int idgrup1, int idgrup2, int idgrup3, string pershkrimi, int idkrijuesi)
        {

            dbManager.Open();
            dbManager.CreateParameters(23);
            dbManager.AddParameters(0, "@IDKOKA", idKoka, ParameterDirection.Output);
            dbManager.AddParameters(1, "@IDNIVEL", idNiv, ParameterDirection.Input);
            dbManager.AddParameters(2, "@IDKONFIGAMBJENTE", idKonf, ParameterDirection.Input);

            if (idMag == 0 || idMag == -1)
                dbManager.AddParameters(3, "@IDMAG", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(3, "@IDMAG", idMag, ParameterDirection.Input);
            dbManager.AddParameters(4, "@NRDOK", nrDk, ParameterDirection.Input);
