        /// <param name="adr"> adresa e njesise administrative</param>
        /// <param name="akt">gjendja nese eshte aktive apo jo</param>
        /// <param name="dtRegj"> data e regjistrimit</param>
        /// <param name="idNjes"> id ritese e njesise administrative</param>
        /// <param name="idPerd">id e perdoruesit qe e ka ruajtur</param>
        /// <param name="kod">kodi i njesise administrative</param>
        /// <param name="nderm">id e ndermarjes</param>
        /// <param name="pershk"> pershkrimi</param>
        /// <returns> nje objekt clsMesazh qe tregon nese ruajtja eshte kryer ne rregull apo jo.</returns>
        /// </summary>
        internal clsMesazh ruajDegeAdministrative(out int iddegeadministrative, string kod, string pershk, string adr, bool akt, DateTime dtRegj, int nderm, int idPerd, int idkonf, int idstatusdok, int qenderkosto, int idskemaqendrakosto, int llojqendre, string kodNjesieBiznesi, bool klientFiskalizimi)
        {
            iddegeadministrative = 0;

            dbManager.Open();
            if(klientFiskalizimi)
                dbManager.CreateParameters(14);
            else
                dbManager.CreateParameters(13);
            dbManager.AddParameters(0, "@IDDEGEADMINISTRATIVE", iddegeadministrative, ParameterDirection.Output);
            dbManager.AddParameters(1, "@KODI", kod, ParameterDirection.Input);
            dbManager.AddParameters(2, "@PERSHKRIMI", pershk, ParameterDirection.Input);
            dbManager.AddParameters(3, "@ADRESA", adr, ParameterDirection.Input);
            dbManager.AddParameters(4, "@AKTIV", akt, ParameterDirection.Input);
            dbManager.AddParameters(5, "@DATEREGJISTRIMI", dtRegj, ParameterDirection.Input);
            dbManager.AddParameters(6, "@IDNDERMARJE", nderm, ParameterDirection.Input);
            dbManager.AddParameters(7, "@IDPERDORUESI", idPerd, ParameterDirection.Input);
            dbManager.AddParameters(8, "@IDKONFIG", idkonf, ParameterDirection.Input);
            dbManager.AddParameters(9, "@IDSTATUSDOK", idstatusdok, ParameterDirection.Input);
            if (qenderkosto == 0 || qenderkosto == -1) dbManager.AddParameters(10, "@QENDRA_KOSTOS", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(10, "@QENDRA_KOSTOS", qenderkosto, ParameterDirection.Input);
            if (idskemaqendrakosto == 0 || idskemaqendrakosto == -1) dbManager.AddParameters(11, "@IDSKEMAQENDRAKOSTO", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(11, "@IDSKEMAQENDRAKOSTO", idskemaqendrakosto, ParameterDirection.Input);
            dbManager.AddParameters(12, "@LLOJQENDRE", llojqendre, ParameterDirection.Input);
            if(klientFiskalizimi)
                dbManager.AddParameters(13, "@KODNJESIEBIZNES", kodNjesieBiznesi, ParameterDirection.Input);
            dbManager.ExecuteNonQuery(CommandType.StoredProcedure, "prc_T_DEGEADMINISTRATIVE_ins");
            iddegeadministrative = int.Parse(dbManager.Parameters[0].Value.ToString());
            clsMesazh mesazh = new clsMesazh(true, MessagesResource.Messages["mesazhRuajtjeMeSukses"]);
            return mesazh;

        }

        /// <summary>
        /// perdoret per te kontrolluar nqs ekziston nje njesi administrative me nje kod te marre si parameter
        /// behet kontrolli per qellime konsistence te informacionit ne DB, nuk lejon te celen njesi administrative  te ndryshem me te njejtin kod ne nje ndermarje
        /// </summary>
        /// <param name="kod">kodi i njesise administrative</param>
        /// <param name="nderm">id e ndermarjes</param>
        /// <returns>nje objeckt boolean qe tregon nese ekziston apo jo nje njesi administrative me kete kod</returns>
        public bool ekzistonKodDegeAdministrative(string kod, int nderm)
        {
            ImbLogger.LogTraceShitje($"Filloi metoda ekzistonKodDegeAdministrative ne DB sipas kod:{kod}, nderm:{nderm}");
            dbManager.Open();
            dbManager.CreateParameters(2);
            dbManager.AddParameters(0, "@KODI", kod, ParameterDirection.Input);
            dbManager.AddParameters(1, "@IDNDERMARJE", nderm, ParameterDirection.Input);
            DataSet ds = dbManager.ExecuteDataSet(CommandType.StoredProcedure, "prc_T_DEGEADMINISTRATIVE_ekzistonKod");
            ImbLogger.LogTraceShitje($"Filloi metoda ekzistonKodDegeAdministrative ne DB sipas kod:{kod}, nderm:{nderm}");
            if (ds.Tables[0].Rows.Count == 1)
            {
                ImbLogger.LogTraceShitje($"U gjet Dege administrative sipas kod:{kod} dhe nderm:{nderm}");
                return true;
            }
            else if (ds.Tables[0].Rows.Count == 0)
            {
                ImbLogger.LogTraceShitje($"Nuk gjet Dege administrative sipas kod:{kod} dhe nderm:{nderm}");
                return false;
            }
                
            else return true;

        }

