        /// <summary>
        /// ekzekuton prc_T_KOKAMBYLLJEKF_ins ne DB dhe kthen statusin e perfundimit te ekzekutimit te SP-se perkatese
        /// Shiko clsMesazh brenda ketij moduli per informacion te metejshem mbi vleren e kthimit te kesaj metode
        /// <returns> nje objekt clsMesazh qe tregon nese ruajtja eshte kryer ne rregull apo jo.</returns>
        /// </summary>
        internal clsMesazh ruajKokaMbylljeKF(out int idKoka, string nrDok, DateTime dateDok, DateTime dateRegjistrimi, int idLlogariDebi, int idLlogariKredi, string pershkrimi, int idNdermarrje, int idNderViti, int idPerdorues, int idNivel, int idKonfigAmbjente, int idDokNga, int idNivelGjenerues, int idKonfigGjenerues, int idGjenerues, int idStatusDok)
        {
            idKoka = -1;

            dbManager.Open();
            dbManager.CreateParameters(17);
            dbManager.AddParameters(0, "@IDKOKA", idKoka, ParameterDirection.Output);
            dbManager.AddParameters(1, "@NRDOK", nrDok, ParameterDirection.Input);
            dbManager.AddParameters(2, "@DTDOK", dateDok, ParameterDirection.Input);
            dbManager.AddParameters(3, "@DTREGJ", dateRegjistrimi, ParameterDirection.Input);
            if (idLlogariDebi == 0 || idLlogariDebi == -1)
                dbManager.AddParameters(4, "@idLLOGDEBI", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(4, "@idLLOGDEBI", idLlogariDebi, ParameterDirection.Input);
            if (idLlogariKredi == 0 || idLlogariKredi == -1)
                dbManager.AddParameters(5, "@idLLOGKREDI", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(5, "@idLLOGKREDI", idLlogariKredi, ParameterDirection.Input);
            dbManager.AddParameters(6, "@PERSHKRIMI", pershkrimi, ParameterDirection.Input);
            dbManager.AddParameters(7, "@IDNDERMARJE", idNdermarrje, ParameterDirection.Input);
            dbManager.AddParameters(8, "@IDNDERVITI", idNderViti, ParameterDirection.Input);
            dbManager.AddParameters(9, "@IDPERDORUESI", idPerdorues, ParameterDirection.Input);
            dbManager.AddParameters(10, "@IDNIVEL", idNivel, ParameterDirection.Input);
            dbManager.AddParameters(11, "@IDKONFIGAMBJENTE", idKonfigAmbjente, ParameterDirection.Input);
            if (idDokNga == 0)
                dbManager.AddParameters(12, "@IDDOKNGA", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(12, "@IDDOKNGA", idDokNga, ParameterDirection.Input);
            if (idNivelGjenerues == 0) dbManager.AddParameters(13, "@IDNIVELGJENERUES", DBNull.Value, ParameterDirection.Input);
            else dbManager.AddParameters(13, "@IDNIVELGJENERUES", idNivelGjenerues, ParameterDirection.Input);
            if (idKonfigGjenerues == 0) dbManager.AddParameters(14, "@IDKONFIGGJENERUES", DBNull.Value, ParameterDirection.Input);
