        #region Faza Kontrate
        internal clsMesazh ruajFaza(out int idFaza, int idKontrata, string pershkrimi, int vlera, DateTime data, int dite, int idstatusdok, int idNdermarje, int idKrijuesi)
        { //metoda per ruajtjen e kartes
            idFaza = -1;

            dbManager.Open();
            clsMesazh mesazh = new clsMesazh();
            //shtimi i parametrave
            dbManager.CreateParameters(9);
            dbManager.AddParameters(0, "@IDFAZA", idFaza, ParameterDirection.Output);
            dbManager.AddParameters(1, "@IDKONTRATA", idKontrata, ParameterDirection.Input);
            dbManager.AddParameters(2, "@PERSHKRIM", pershkrimi, ParameterDirection.Input);
            dbManager.AddParameters(3, "@VLERA", vlera, ParameterDirection.Input);
            dbManager.AddParameters(4, "@DATA", data, ParameterDirection.Input);
            dbManager.AddParameters(5, "@DITE", dite, ParameterDirection.Input);
            dbManager.AddParameters(6, "@IDSTATUSDOK", idstatusdok, ParameterDirection.Input);
            dbManager.AddParameters(7, "@IDNDERMARRJE", idNdermarje, ParameterDirection.Input);
            dbManager.AddParameters(8, "@IDKRIJUES", idKrijuesi, ParameterDirection.Input);



            dbManager.ExecuteNonQuery(CommandType.StoredProcedure, "prc_T_KONTRATAFAZA_ins");
